    'landing.testimonial_title': 'Khách hàng Nói gì?',
    'landing.testimonial_desc1': 'ScopeGraph nhận được sự đánh giá cao từ các nhà phát triển và kiến trúc sư AI trên toàn cầu.',
    'landing.testimonial_desc2': 'Các đội ngũ kỹ thuật đã loại bỏ hoàn toàn các chỉnh sửa ảo giác và lỗi migration cơ sở dữ liệu trước khi đưa lên production.',
    'landing.testimonial_desc3': 'Bạn đã sẵn sàng chưa? Trải nghiệm đồ thị tương tác để trực tiếp nhìn thấy bán kính ảnh hưởng.',
    'landing.testimonial_btn': 'Viết nhận xét của bạn',
