    'landing.news_card1_title': 'ScopeGraph đạt chuẩn xác minh bán kính ảnh hưởng không ảo giác tại Meta Hackathon 2026',
    'landing.news_card1_desc': 'Bằng việc kết hợp phân tích AST tất định với cổng kiểm chứng bằng chứng, ScopeGraph đảm bảo mọi nhận định đều dựa trên mã nguồn thực tế...',
    'landing.news_card2_title': 'Điều phối Đa-AI: Định tuyến thông minh giữa Meta Model API, Modal và Baseten Vision',
    'landing.news_card2_desc': 'Cách suy luận AI phân tầng mang lại khả năng phân tích bán kính ảnh hưởng dưới 1 giây mà không làm phình context hay sinh lỗi ảo giác...',
    'landing.news_card3_title': 'Tại sao AI Coding Agent cần Đồ thị Mã nguồn Tất định thay vì nhồi nhét Toàn bộ Codebase',
    'landing.news_card3_desc': 'Context window có giới hạn và tốn kém. Công cụ FastMCP của ScopeGraph cung cấp chính xác cây gọi hàm và dòng code theo yêu cầu...',
    'landing.news_card4_title': 'Phát hiện Tác động Schema Alembic & SQLAlchemy cho các Bản phát hành Zero-Downtime',
