    'docs.section_overview_title': '1. 플랫폼 개요',
    'docs.section_overview_desc': '코드 커밋 전 영향 반경을 분석하여 추측과 AI 환각을 사전에 차단합니다.',
    'docs.section_arch_title': '2. 다단계 분석 아키텍처',
    'docs.section_arch_desc': '7단계 분석 파이프라인이 AST 기호를 파싱하고 NetworkX 종속성 그래프를 구축합니다.',
