    'docs.section_overview_title': '1. Plattform-Übersicht',
    'docs.section_overview_desc': 'Beseitigt Spekulationen und KI-Halluzinationen durch Auswirkungsanalysen vor dem Commit.',
    'docs.section_arch_title': '2. Mehrstufige Analysearchitektur',
    'docs.section_arch_desc': '7-stufige Pipeline parst AST-Symbole, erstellt NetworkX-Graphen und validiert alle Behauptungen.',
