    'privacy.badge': 'Rechtsdokument • v2.4',
    'privacy.title': 'Datenschutzerklärung',
    'privacy.subtitle': 'How ScopeGraph protects your codebase, intellectual property, and personal data under GDPR, CCPA, and global security standards.',
    'privacy.last_updated': 'Effective Date: November 2026',
    'privacy.toc_title': 'Table of Contents',
    'privacy.contact_card_title': 'Data Protection Officer',
    'privacy.contact_card_desc': 'Questions or data deletion requests? Contact our dedicated security team.',
    'privacy.download_btn': 'Print / Save PDF',
    'privacy.s1_title': '1. Introduction & Scope',
    'privacy.s1_desc': 'ScopeGraph Inc. operates the ScopeGraph code intelligence platform, including web applications, REST APIs, FastMCP servers, and background workers. This Privacy Policy governs how we handle, isolate, and protect your information.',
    'privacy.s2_title': '2. Information We Collect',
    'privacy.s2_desc': 'We collect only minimal necessary data: identity tokens (GitHub OAuth), AST structural metadata (classes, methods, endpoints, database schemas), operational telemetry, and Stripe billing status without storing raw cardholder details.',
    'privacy.s3_title': '3. Zero-Training Guarantee on Customer Code',
    'privacy.s3_desc': 'YOUR SOURCE CODE IS NEVER USED TO TRAIN PUBLIC OR FOUNDATIONAL AI MODELS. Prompts and semantic context processed through Meta AI (Muse-Spark / Llama-3.3) are ephemeral and covered by strict zero-retention enterprise agreements.',
    'privacy.s4_title': '4. AST Sandboxing & Zip-Slip Protection',
    'privacy.s4_desc': 'All repository indexing occurs within sandboxed directories with canonical path checking to prevent Zip-Slip vulnerabilities. PostgreSQL stores only structural symbol graphs, never raw entire repository archives.',
    'privacy.s5_title': '5. Sub-processors & Cloud Services',
    'privacy.s5_desc': 'We work exclusively with certified sub-processors: Stripe for PCI-DSS billing, GitHub for OAuth authentication, Meta AI and certified inference partners for stateless analysis, and SOC2 Type II cloud infrastructure.',
    'privacy.s6_title': '6. Global Privacy Rights (GDPR & CCPA)',
    'privacy.s6_desc': 'Users worldwide possess the right to access, export, rectify, or permanently erase their personal data and indexed repositories. You may exercise your right to be forgotten at any time.',
    'privacy.s7_title': '7. Data Retention & Deletion Lifecycle',
    'privacy.s7_desc': 'When you delete a repository or delete your account, all associated workspace files, AST symbols, dependency edges, and cached analysis reports are permanently scrubbed within 24 hours.',
    'privacy.s8_title': '8. Technical Security & Encryption',
    'privacy.s8_desc': 'We apply defense-in-depth protections including TLS 1.3 transit encryption, AES-256 storage encryption, database tenant isolation, and strict sandbox resource quotas.',
    'privacy.s9_title': '9. Cookie & Local Storage Policy',
    'privacy.s9_desc': 'ScopeGraph uses no third-party tracking cookies or advertising pixels. Local browser storage is used strictly for authentication sessions, interface language, and UI display settings.',
    'privacy.s10_title': '10. Contact & Privacy Inquiries',
    'privacy.s10_desc': 'For privacy compliance, data processing agreements (DPA), or inquiries, contact our Data Protection Officer at privacy@scopegraph.top.',
    'terms.badge': 'Rechtsdokument • v2.4',
    'terms.title': 'Nutzungsbedingungen',
    'terms.subtitle': 'Binding terms and conditions governing your access to the ScopeGraph code intelligence platform, MCP tools, and APIs.',
    'terms.last_updated': 'Effective Date: November 2026',
    'terms.toc_title': 'Table of Contents',
    'terms.help_card_title': 'Need Legal Assistance?',
    'terms.help_card_desc': 'For enterprise Master Services Agreements (MSA) or custom terms, reach out to our legal department.',
    'terms.download_btn': 'Print / Save PDF',
    'terms.s1_title': '1. Acceptance of Terms & Eligibility',
    'terms.s1_desc': 'By accessing or using ScopeGraph via web interface, REST API, or Model Context Protocol (MCP), you agree to be bound by these legally binding terms. If acting for an organization, you warrant authority to bind that entity.',
    'terms.s2_title': '2. Description of Service & MCP Access',
    'terms.s2_desc': 'ScopeGraph provides developer intelligence tools including static AST analysis, blast radius calculation, and native FastMCP tools (analyze_change, get_relevant_context, suggest_tests). We grant you a revocable, non-exclusive license to use the service.',
    'terms.s3_title': '3. Customer Intellectual Property & Code Ownership',
    'terms.s3_desc': 'YOU RETAIN 100% EXCLUSIVE OWNERSHIP OF ALL INTELLECTUAL PROPERTY in your source code, repositories, commit history, and software architecture. ScopeGraph claims zero rights or ownership over your code.',
    'terms.s4_title': '4. Acceptable Use Policy',
    'terms.s4_desc': 'You agree not to upload malicious payloads, exploit Zip-Slip path traversal, reverse-engineer graph traversal engines, bypass sandbox quotas, or scrape platform outputs to develop competing tools.',
    'terms.s5_title': '5. Subscription Plans, Billing & Stripe Payments',
    'terms.s5_desc': 'Paid subscriptions are billed on a recurring monthly or annual basis via Stripe. Fees are non-refundable except where mandated by law. You may cancel at any time, retaining access until the end of the billing period.',
    'terms.s6_title': '6. Advisory Nature of AI & Disclaimers',
    'terms.s6_desc': 'While the Anti-Hallucination Evidence Gate validates claims against database records, AI reasoning outputs and blast radius reports are advisory aids. Human review and automated testing remain mandatory before production deployments.',
    'terms.s7_title': '7. Service Availability & SLA',
    'terms.s7_desc': 'We strive to deliver 99.9% uptime for cloud services. Service may be subject to brief maintenance windows, with reasonable advance notice provided for planned downtime.',
    'terms.s8_title': '8. Limitation of Liability & Warranty Disclaimer',
    'terms.s8_desc': 'ScopeGraph is provided \'AS IS\' without warranties of any kind. To the maximum extent permitted by law, ScopeGraph\'s total aggregate liability shall not exceed the fees paid by you in the preceding 12 months.',
    'terms.s9_title': '9. Term, Suspension & Termination',
    'terms.s9_desc': 'We reserve the right to suspend or terminate accounts that breach the Acceptable Use Policy or security sandboxing restrictions, following written notification where practicable.',
    'terms.s10_title': '10. Governing Law & Dispute Resolution',
    'terms.s10_desc': 'These Terms are governed by the laws of California, United States. Any disputes shall be resolved in the state or federal courts located in San Francisco, California. Contact: legal@scopegraph.top.',
    'assistant.unsure': 'Dazu liegen mir noch keine verifizierten Informationen vor. Bitte sieh in der ScopeGraph-Dokumentation nach.',
    'assistant.welcome_heading': 'Scout sagt Hallo!',
    'assistant.options': 'Chatoptionen',
    'assistant.quick_actions': 'Schnellaktionen',
    'assistant.footer_disclaimer': 'Scout kann ungenau sein. Bitte überprüfe wichtige Angaben.',
