    'dash.tour_step_graph_tip': 'Значения цветов рамок узлов:\n• **Зелёная рамка**: Исходная точка изменений в коде\n• **Синяя рамка**: Цепочка косвенного влияния ниже по потоку\n• **Серая рамка**: Безопасные, незатронутые компоненты',
